nt;\r\n\r\n    try {\r\n      account = getAuthenticatedAccount(response);\r\n    } catch (error) {\r\n      next(error);\r\n      return;\r\n    }\r\n\r\n    void service\r\n      .requestAccess(account, parsed.data)\r\n      .then((result) => {\r\n        response.status(201).json(submitterAccessRequestResponseSchema.parse(result));\r\n      })\r\n      .catch((error: unknown) => {\r\n        if (error instanceof SubmitterAccessConflictError) {\r\n          response.status(409).json({\r\n            error: {\r\n              code: error.code,\r\n              message: error.message,\r\n            },\r\n          });\r\n          return;\r\n        }\r\n\r\n        if (error instanceof InvalidRequestedCompetitionError) {\r\n          response.status(422).json({\r\n            error: {\r\n              code: 'INVALID_COMPETITION_SCOPE',\r\n              message: error.message,\r\n              details: [\r\n                {\r\n                  code: 'INVALID_SCOPE',\r\n                  field: 'competitionId',\r\n                  message: 'Select a competition that currently exists.',\r\n                },\r\n              ],\r\n            },\r\n          });\r\n          return;\r\n        }\r\n\r\n        next(error);\r\n      });\r\n  };\r\n}\r\n\r\nfunction isDatabaseIdentifier(value: string): boolean {\r\n  if (!/^[1-9]\\d*$/.test(value)) {\r\n    return false;\r\n  }\r\n\r\n  try {\r\n    return BigInt(value) <= 9_223_372_036_854_775_807n;\r\n  } catch {\r\n    return false;\r\n  }\r\n}\r\nimport type {\r\n  SubmitterAccessRequest,\r\n  SubmitterAccessRequestResponse,\r\n} from '@sport-analytics/contracts';\r\nimport type { ApplicationAccount } from '../accounts/account';\r\nimport { SubmitterAccessConflictError } from './submitter-access.errors';\r\nimport {\r\n  createSubmitterAccessRepository,\r\n  type SubmitterAccessRepository,\r\n} from './submitter-access.repository';\r\n\r\nexport interface SubmitterAccessService {\r\n  requestAccess(\r\n    account: ApplicationAccount,\r\n    request: SubmitterAccessRequest,\r\n  ): Promise<SubmitterAccessRequestResponse>;\r\n}\r\n\r\nexport function createSubmitterAccessService(\r\n  repository?: SubmitterAccessRepository,\r\n): SubmitterAccessService {\r\n  let resolvedRepository = repository;\r\n\r\n  return {\r\n    async requestAccess(account, request) {\r\n      if (account.role === 'submitter' || account.role === 'admin') {\r\n        throw new SubmitterAccessConflictError(\r\n          'SUBMITTER_ALREADY_APPROVED',\r\n          'The authenticated account already has submission access.',\r\n        );\r\n      }\r\n\r\n      resolvedRepository ??= createSubmitterAccessRepository();\r\n      const persistedRequest = await resolvedRepository.requestAccess(\r\n        account.accountId,\r\n        request.competitionId,\r\n      );\r\n\r\n      return {\r\n        data: persistedRequest,\r\n      };\r\n    },\r\n  };\r\n}\r\nimport { z } from 'zod';\r\n\r\nimport { apiDateTimeSchema, apiIdentifierSchema } from './api';\r\n\r\nexport const APPLICATION_ROLES = ['viewer', 'submitter', 'admin'] as const;\r\n\r\nexport const applicationRoleSchema = z.enum(APPLICATION_ROLES);\r\n\r\n/** @deprecated Request-workflow state only. Use applicationRoleSchema for authorization. */\r\nexport const submitterApprovalStateSchema = z.enum([\r\n  'not_requested',\r\n  'pending',\r\n  'approved',\r\n  'rejected',\r\n]);\r\n\r\nexport const competitionScopeSchema = z\r\n  .object({\r\n    competitionId: apiIdentifierSchema,\r\n    name: z.string().min(1),\r\n  })\r\n  .strict();\r\n\r\nexport const currentUserProfileSchema = z\r\n  .object({\r\n    id: apiIdentifierSchema,\r\n    subject: z.string().min(1),\r\n    displayName: z.string().min(1).nullable(),\r\n    role: applicationRoleSchema,\r\n    approvalState: submitterApprovalStateSchema,\r\n    requestedCompetition: competitionScopeSchema.nullable(),\r\n    competitionIds: z\r\n      .array(apiIdentifierSchema)\r\n      .refine((competitionIds) => new Set(competitionIds).size === competitionIds.length, {\r\n        message: 'Competition identifiers must be unique.',\r\n      }),\r\n  })\r\n  .strict();\r\n\r\nexport const currentUserProfileResponseSchema = z\r\n  .object({\r\n    user: currentUserProfileSchema,\r\n  })\r\n  .strict();\r\n\r\nexport const accountDeletionRequestSchema = z\r\n  .object({\r\n    confirmation: z.literal('DELETE'),\r\n  })\r\n  .strict();\r\n\r\nexport const accountDeletionResponseSchema = z\r\n  .object({\r\n    data: z\r\n      .object({\r\n        status: z.literal('deleted'),\r\n        retainedCricketData: z.literal(true),\r\n      })\r\n      .strict(),\r\n  })\r\n  .strict();\r\n\r\nexport const submitterAccessRequestSchema = z\r\n  .object({\r\n    competitionId: apiIdentifierSchema,\r\n  })\r\n  .strict();\r\n\r\nexport const submitterAccessRequestResponseSchema = z\r\n  .object({\r\n    data: z\r\n      .object({\r\n        accountId: apiIdentifierSchema,\r\n        approvalState: z.literal('pending'),\r\n        requestedCompetition: competitionScopeSchema,\r\n      })\r\n      .strict(),\r\n  })\r\n  .strict();\r\n\r\nexport const administratorCompetitionScopeSchema = competitionScopeSchema;\r\n\r\nexport const administratorAuditActorSchema = z\r\n  .object({\r\n    id: apiIdentifierSchema,\r\n    displayName: z.string().min(1).nullable(),\r\n  })\r\n  .strict();\r\n\r\nexport const administratorManagedUserSchema = z\r\n  .object({\r\n    id: apiIdentifierSchema,\r\n    displayName: z.string().min(1).nullable(),\r\n    role: applicationRoleSchema,\r\n    approvalState: submitterApprovalStateSchema,\r\n    requestedCompetition: competitionScopeSchema.nullable(),\r\n    competitionScopes: z\r\n      .array(administratorCompetitionScopeSchema)\r\n      .refine(\r\n        (scopes) => new Set(scopes.map((scope) => scope.competitionId)).size === scopes.length,\r\n        { message: 'Competition scopes must be unique.' },\r\n      ),\r\n    disabled: z.boolean(),