for authorization. */\r\nexport type SubmitterApprovalState = z.infer<typeof submitterApprovalStateSchema>;\r\nexport type CurrentUserProfile = z.infer<typeof currentUserProfileSchema>;\r\nexport type CurrentUserProfileResponse = z.infer<typeof currentUserProfileResponseSchema>;\r\nexport type AccountDeletionRequest = z.infer<typeof accountDeletionRequestSchema>;\r\nexport type AccountDeletionResponse = z.infer<typeof accountDeletionResponseSchema>;\r\nexport type CompetitionScope = z.infer<typeof competitionScopeSchema>;\r\nexport type SubmitterAccessRequest = z.infer<typeof submitterAccessRequestSchema>;\r\nexport type SubmitterAccessRequestResponse = z.infer<typeof submitterAccessRequestResponseSchema>;\r\nexport type AdministratorCompetitionScope = z.infer<typeof administratorCompetitionScopeSchema>;\r\nexport type AdministratorManagedUser = z.infer<typeof administratorManagedUserSchema>;\r\nexport type AdministratorUserManagementResponse = z.infer<\r\n  typeof administratorUserManagementResponseSchema\r\n>;\r\nexport type AdministratorSubmitterAccessUpdate = z.infer<\r\n  typeof administratorSubmitterAccessUpdateSchema\r\n>;\r\nexport type AdministratorSubmitterAccessResponse = z.infer<\r\n  typeof administratorSubmitterAccessResponseSchema\r\n>;\r\nimport {\r\n  submitterAccessRequestResponseSchema,\r\n  type Competition,\r\n  type SubmitterAccessRequestResponse,\r\n} from '@sport-analytics/contracts';\r\nimport type { AuthenticatedApiClient } from '../../api/client';\r\nimport { publicReadApi } from '../../api/public-read';\r\n\r\nexport class SubmitterAccessContractError extends Error {\r\n  constructor() {\r\n    super('The API returned an unexpected submitter access response. Please try again.');\r\n    this.name = 'SubmitterAccessContractError';\r\n  }\r\n}\r\n\r\nexport class SubmitterAccessCompetitionOptionsError extends Error {\r\n  constructor() {\r\n    super('Available competitions could not be loaded. Please try again.');\r\n    this.name = 'SubmitterAccessCompetitionOptionsError';\r\n  }\r\n}\r\n\r\nexport async function listRequestableCompetitions(signal?: AbortSignal): Promise<Competition[]> {\r\n  const competitions: Competition[] = [];\r\n  let cursor: string | null = null;\r\n\r\n  try {\r\n    do {\r\n      const parameters = new URLSearchParams({ limit: '100' });\r\n      if (cursor) {\r\n        parameters.set('cursor', cursor);\r\n      }\r\n\r\n      const response = await publicReadApi.listCompetitions(`?${parameters.toString()}`, signal);\r\n      competitions.push(...response.data);\r\n      cursor = response.pagination.nextCursor;\r\n    } while (cursor);\r\n  } catch {\r\n    throw new SubmitterAccessCompetitionOptionsError();\r\n  }\r\n\r\n  return competitions.sort(\r\n    (left, right) =>\r\n      left.name.localeCompare(right.name) || left.competitionId.localeCompare(right.competitionId),\r\n  );\r\n}\r\n\r\nexport async function requestSubmitterAccess(\r\n  client: AuthenticatedApiClient,\r\n  competitionId: string,\r\n): Promise<SubmitterAccessRequestResponse> {\r\n  const response = await client.request<unknown>('/submitter-access-requests', {\r\n    method: 'POST',\r\n    headers: {\r\n      'Content-Type': 'application/json',\r\n    },\r\n    body: JSON.stringify({ competitionId }),\r\n  });\r\n  const parsed = submitterAccessRequestResponseSchema.safeParse(response);\r\n\r\n  if (!parsed.success) {\r\n    throw new SubmitterAccessContractError();\r\n  }\r\n\r\n  return parsed.data;\r\n}\r\n"},{"type":"input_text","text":"EXIT 0"}],"internal_chat_message_metadata_passthrough":{"turn_id":"01a03f37-16af-76c1-b09e-c41792572355","create_time":1787769288.9402466}}}
