import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';
import { isSubmitterApprovalState } from '../accounts/account';
import {
  InvalidRequestedCompetitionError,
  SubmitterAccessConflictError,
} from './submitter-access.errors';

interface SubmitterAccessRequestRecord {
  accountId: string;
  approvalState: 'pending';
  requestedCompetition: { competitionId: string; name: string };
}

export interface SubmitterAccessRepository {
  requestAccess(accountId: string, competitionId: string): Promise<SubmitterAccessRequestRecord>;
}

interface SubmitterAccessRow {
  accountId: string;
  approvalState: string;
  disabledAt: Date | null;
  competitionExists?: boolean;
  requestedCompetitionId?: string;
  requestedCompetitionName?: string;
}

export function createSubmitterAccessRepository(
  executor: QueryExecutor = getDatabasePool(),
): SubmitterAccessRepository {
  return {
    async requestAccess(accountId, competitionId) {
      const updated = await executeQuery<SubmitterAccessRow>(
        executor,
        `
          WITH requested_competition AS (
            SELECT competition_id, name
            FROM competition
            WHERE competition_id = $2
          ),
          updated_account AS (
            UPDATE app_user account
            SET
              submitter_approval_state = 'pending',
              submitter_requested_competition_id = requested_competition.competition_id
            FROM requested_competition
            WHERE account.app_user_id = $1
              AND account.submitter_approval_state IN ('not_requested', 'rejected')
              AND account.disabled_at IS NULL
            RETURNING
              account.app_user_id::text AS "accountId",
              account.submitter_approval_state AS "approvalState",
              account.disabled_at AS "disabledAt",
              requested_competition.competition_id::text AS "requestedCompetitionId",
              requested_competition.name AS "requestedCompetitionName"
          )
          SELECT * FROM updated_account
        `,
        [accountId, competitionId],
      );

      const created = updated.rows[0];

      if (created) {
        return {
          accountId: created.accountId,
          approvalState: 'pending',
          requestedCompetition: {
            competitionId: created.requestedCompetitionId!,
            name: created.requestedCompetitionName!,
          },
        };
      }

      const current = await executeQuery<SubmitterAccessRow>(
        executor,
        `
          SELECT
            app_user_id::text AS "accountId",
            submitter_approval_state AS "approvalState",
            disabled_at AS "disabledAt",
            EXISTS (
              SELECT 1
              FROM competition
              WHERE competition_id = $2
            ) AS "competitionExists"
          FROM app_user
          WHERE app_user_id = $1
        `,
        [accountId, competitionId],
      );

      const account = current.rows[0];

      if (!account) {
        throw new Error('Authenticated application account no longer exists');
      }

      if (account.disabledAt) {
        throw new Error('Authenticated application account became disabled');
      }

      if (!isSubmitterApprovalState(account.approvalState)) {
        throw new Error('Application account has an unsupported approval state');
      }

      if (account.approvalState === 'pending') {
        throw new SubmitterAccessConflictError(
          'REQUEST_ALREADY_PENDING',
          'A submitter access request is already pending.',
        );
      }

      if (account.approvalState === 'approved') {
        throw new SubmitterAccessConflictError(
          'SUBMITTER_ALREADY_APPROVED',
          'The authenticated account is already an approved submitter.',
        );
      }

      if (!account.competitionExists) {
        throw new InvalidRequestedCompetitionError();
      }

      throw new Error('Submitter access request state changed unexpectedly');
    },
  };
}
import type {
  SubmitterAccessRequest,
  SubmitterAccessRequestResponse,
} from '@sport-analytics/contracts';
import type { ApplicationAccount } from '../accounts/account';
import { SubmitterAccessConflictError } from './submitter-access.errors';
import {
  createSubmitterAccessRepository,
  type SubmitterAccessRepository,
} from './submitter-access.repository';

export interface SubmitterAccessService {
  requestAccess(
    account: ApplicationAccount,
    request: SubmitterAccessRequest,
  ): Promise<SubmitterAccessRequestResponse>;
}

export function createSubmitterAccessService(
  repository?: SubmitterAccessRepository,
): SubmitterAccessService {
  let resolvedRepository = repository;

  return {
    async requestAccess(account, request) {
      if (account.role === 'submitter' || account.role === 'admin') {
        throw new SubmitterAccessConflictError(
          'SUBMITTER_ALREADY_APPROVED',
          'The authenticated account already has submission access.',
        );
      }

      resolvedRepository ??= createSubmitterAccessRepository();
      const persistedRequest = await resolvedRepository.requestAccess(
        account.accountId,
        request.competitionId,
      );

      return {
        data: persistedRequest,
      };
    },
  };
}
import {
  submitterAccessRequestResponseSchema,
  submitterAccessRequestSchema,
} from '@sport-analytics/contracts';
import type { RequestHandler, Response } from 'express';

import type { ApplicationAccount } from '../accounts/account';
import {
  InvalidRequestedCompetitionError,
  SubmitterAccessConflictError,
} from './submitter-access.errors';
import type { SubmitterAccessService } from './submitter-access.service';

function getAuthenticatedAccount(response: Response): ApplicationAccount {
  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;

  if (!account) {
    throw new Error('Submitter access controller requires an authenticated application account');
  }

  return account;
}

export function createSubmitterAccessController(service: SubmitterAccessService): RequestHandler {
  return (request, response, next) => {
    const parsed = submitterAccessRequestSchema.safeParse(request.body);

    if (!parsed.success || !isDatabaseIdentifier(parsed.data.competitionId)) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The submitter access request is invalid.',
          details: [
            {
              code: 'INVALID_FIELD',
              field: 'competitionId',
              message: 'Select a valid competition.',
            },
          ],
        },
      });
      return;
    }

    let account: ApplicationAccount;

    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .requestAccess(account, parsed.data)
      .then((result) => {
        response.status(201).json(submitterAccessRequestResponseSchema.parse(result));
      })
      .catch((error: unknown) => {
        if (error instanceof SubmitterAccessConflictError) {
          response.status(409).json({
            error: {
              code: error.code,
              message: error.message,
            },
          });
          return;
        }

        if (error instanceof InvalidRequestedCompetitionError) {
          response.status(422).json({
            error: {
              code: 'INVALID_COMPETITION_SCOPE',
              message: error.message,
              details: [
                {
                  code: 'INVALID_SCOPE',
                  field: 'competitionId',
                  message: 'Select a competition that currently exists.',
                },
              ],
            },
          });
          return;
        }

        next(error);
      });
  };
}

function isDatabaseIdentifier(value: string): boolean {
  if (!/^[1-9]\d*$/.test(value)) {
    return false;
  }

  try {
    return BigInt(value) <= 9_223_372_036_854_775_807n;
  } catch {
    return false;
  }
}
import type { Competition, CurrentUserProfile } from '@sport-analytics/contracts';
import { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { ApiResponseError } from '../../api/client';
import { CurrentUserContractError, getCurrentUserProfile } from '../auth/current-user-api';
import { useAuthenticatedApiClient } from '../auth/useAuthenticatedApiClient';
import {
  listRequestableCompetitions,
  requestSubmitterAccess,
  SubmitterAccessCompetitionOptionsError,
  SubmitterAccessContractError,
} from './submitter-access-api';

type ProfileState =
  | { kind: 'loading' }
  | { kind: 'error'; message: string }
  | { kind: 'ready'; profile: CurrentUserProfile; competitions: Competition[] };

type Feedback = { kind: 'success' | 'error'; message: string } | null;

function hasSubmissionRole(profile: CurrentUserProfile): boolean {
  return profile.role === 'submitter' || profile.role === 'admin';
}

function canRequestAccess(profile: CurrentUserProfile): boolean {
  return (
    profile.role === 'viewer' &&
    (profile.approvalState === 'not_requested' || profile.approvalState === 'rejected')
  );
}

function profileErrorMessage(error: unknown): string {
  if (error instanceof ApiResponseError && error.kind === 'unauthenticated') {
    return 'Your session is no longer valid. Sign in again to check your submitter status.';
  }

  if (error instanceof CurrentUserContractError) {
    return error.message;
  }

  if (error instanceof SubmitterAccessCompetitionOptionsError) {
    return error.message;
  }

  return 'Your submitter status could not be loaded. Please try again.';
}

function requestErrorMessage(error: unknown): string {
  if (error instanceof ApiResponseError && error.kind === 'unauthenticated') {
    return 'Your session is no longer valid. Sign in again before requesting access.';
  }

  if (error instanceof ApiResponseError || error instanceof SubmitterAccessContractError) {
    return error.message;
  }

  return 'Your request could not be submitted. Please try again.';
}

export function SubmitterAccessPanel() {
  const client = useAuthenticatedApiClient();
  const [profileState, setProfileState] = useState<ProfileState>({ kind: 'loading' });
  const [selectedCompetitionId, setSelectedCompetitionId] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [feedback, setFeedback] = useState<Feedback>(null);

  const loadProfile = useCallback(
    async (signal?: AbortSignal) => {
      setProfileState({ kind: 'loading' });

      try {
        const profile = await getCurrentUserProfile(client, signal);
        const competitions = canRequestAccess(profile)
          ? await listRequestableCompetitions(signal)
          : [];
        const requestedCompetitionId = profile.requestedCompetition?.competitionId;
        const initialCompetitionId =
          competitions.find((competition) => competition.competitionId === requestedCompetitionId)
            ?.competitionId ??
          competitions[0]?.competitionId ??
          '';

        setSelectedCompetitionId(initialCompetitionId);
        setProfileState({ kind: 'ready', profile, competitions });
      } catch (error) {
        if (signal?.aborted) {
          return;
        }

        setProfileState({ kind: 'error', message: profileErrorMessage(error) });
      }
    },
    [client],
  );

  useEffect(() => {
    const controller = new AbortController();
    void loadProfile(controller.signal);

    return () => controller.abort();
  }, [loadProfile]);

  async function handleRequest(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (profileState.kind !== 'ready' || !selectedCompetitionId) {
      return;
    }

    const existingProfile = profileState.profile;
    const existingCompetitions = profileState.competitions;
    setIsSubmitting(true);
    setFeedback(null);

    try {
      const result = await requestSubmitterAccess(client, selectedCompetitionId);
      setProfileState({
        kind: 'ready',
        profile: {
          ...existingProfile,
          approvalState: 'pending',
          requestedCompetition: result.data.requestedCompetition,
        },
        competitions: existingCompetitions,
      });
      setFeedback({
        kind: 'success',
        message: `Your request for ${result.data.requestedCompetition.name} was submitted and is now awaiting administrator approval.`,
      });

      try {
        const persistedProfile = await getCurrentUserProfile(client);
        setProfileState({
          kind: 'ready',
          profile: persistedProfile,
          competitions: existingCompetitions,
        });
      } catch {
        setFeedback({
          kind: 'success',
          message:
            'Your request was saved, but the latest account profile could not be refreshed. Reload the page to check it again.',
        });
      }
    } catch (error) {
      if (error instanceof ApiResponseError && error.status === 409) {
        try {
          const persistedProfile = await getCurrentUserProfile(client);
          setProfileState({
            kind: 'ready',
            profile: persistedProfile,
            competitions: existingCompetitions,
          });

          if (
            hasSubmissionRole(persistedProfile) ||
            persistedProfile.approvalState === 'pending' ||
            persistedProfile.approvalState === 'approved'
          ) {
            setFeedback({
              kind: 'success',
              message: 'Your submitter status changed and has been refreshed from your account.',
            });
            return;
          }
        } catch {
          // Keep the original, safe conflict response when the latest profile
          // cannot be loaded.
        }
      }

      setFeedback({ kind: 'error', message: requestErrorMessage(error) });
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <section className="submitter-access-panel" aria-labelledby="submitter-access-title">
      <div className="submitter-access-panel__heading">
        <div>
          <p className="eyebrow">Cricket event contribution</p>
          <h2 id="submitter-access-title">Submitter access</h2>
        </div>
        {profileState.kind === 'ready' ? (
          <p
            className={`submitter-access-state submitter-access-state--${
              profileState.profile.role === 'viewer'
                ? profileState.profile.approvalState
                : profileState.profile.role
            }`}
          >
            {profileState.profile.role === 'admin'
              ? 'Admin'
              : profileState.profile.role === 'submitter'
                ? 'Submitter'
                : profileState.profile.approvalState === 'not_requested'
                  ? 'Not requested'
                  : profileState.profile.approvalState === 'pending'
                    ? 'Pending approval'
                    : profileState.profile.approvalState === 'approved'
                      ? 'Approved'
                      : 'Not approved'}
          </p>
        ) : null}
      </div>

      {profileState.kind === 'loading' ? (
        <p className="submitter-access-panel__message" role="status">
          Loading your persisted submitter statusâ€¦
        </p>
      ) : profileState.kind === 'error' ? (
        <div className="submitter-access-panel__error" role="alert">
          <p>{profileState.message}</p>
          <button
            className="button button--secondary"
            type="button"
            onClick={() => void loadProfile()}
          >
            Retry status check
          </button>
        </div>
      ) : hasSubmissionRole(profileState.profile) ? (
        <div className="submitter-access-panel__message">
          <p>
            Your account has submission access. Submissions remain limited to the competitions
            assigned by an administrator.
          </p>
          <div className="submitter-access-panel__actions">
            <Link className="button button--primary" to="/submissions/new">
              Submit events
            </Link>
            {profileState.profile.role === 'admin' ? (
              <Link className="button button--secondary" to="/admin/users">
                Manage users
              </Link>
            ) : null}
          </div>
        </div>
      ) : profileState.profile.approvalState === 'pending' ? (
        <p className="submitter-access-panel__message" role="status">
          Your request
          {profileState.profile.requestedCompetition
            ? ` for ${profileState.profile.requestedCompetition.name}`
            : ''}{' '}
          is awaiting administrator review. You cannot submit another request while this one is
          pending.
        </p>
      ) : profileState.profile.approvalState === 'approved' ? (
        <p className="submitter-access-panel__message" role="status">
          Your previously approved submitter access has been revoked. Your account no longer permits
          submissions.
        </p>
      ) : (
        <div className="submitter-access-panel__message">
          <p>
            {profileState.profile.approvalState === 'rejected'
              ? 'Your previous request was declined. You can send a new request for review.'
              : 'Request permission to contribute cricket delivery-event data for one competition. An administrator will review the requested competition scope.'}
          </p>
          {profileState.competitions.length > 0 ? (
            <form
              className="submitter-access-request"
              onSubmit={(event) => void handleRequest(event)}
            >
              <label htmlFor="submitter-access-competition">Competition</label>
              <select
                id="submitter-access-competition"
                value={selectedCompetitionId}
                onChange={(event) => setSelectedCompetitionId(event.target.value)}
                disabled={isSubmitting}
              >
                {profileState.competitions.map((competition) => (
                  <option key={competition.competitionId} value={competition.competitionId}>
                    {competition.name}
                  </option>
                ))}
              </select>
              <p className="field-help">
                Approval grants submission access only within this competition.
              </p>
              <button
                className="button button--primary"
                type="submit"
                disabled={isSubmitting || !selectedCompetitionId}
              >
                {isSubmitting ? 'Requesting accessâ€¦' : 'Request submitter access'}
              </button>
            </form>
          ) : (
            <p className="submitter-access-panel__empty" role="status">
              No competitions are currently available for an access request.
            </p>
          )}
        </div>
      )}

      {feedback ? (
        <p
          className={
            feedback.kind === 'error'
              ? 'submitter-access-feedback submitter-access-feedback--error'
              : 'submitter-access-feedback'
          }
          role={feedback.kind === 'error' ? 'alert' : 'status'}
        >
          {feedback.message}
        </p>
      ) : null}
    </section>
  );
}
import type {
  AdministratorCompetitionScope,
  AdministratorManagedUser,
  AdministratorSubmitterAccessUpdate,
} from '@sport-analytics/contracts';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Navigate } from 'react-router-dom';

import { ApiResponseError } from '../../api/client';
import { useAuth } from '../auth/AuthProvider';
import { getCurrentUserProfile } from '../auth/current-user-api';
import { useAuthenticatedApiClient } from '../auth/useAuthenticatedApiClient';
import {
  AdminUserManagementContractError,
  getAdministratorUserManagement,
  rejectAdministratorSubmitterAccessRequest,
  updateAdministratorSubmitterAccess,
} from './admin-api';

interface ManagementData {
  users: AdministratorManagedUser[];
  availableScopes: AdministratorCompetitionScope[];
}

type PageState =
  | { kind: 'loading' }
  | { kind: 'forbidden' }
  | { kind: 'error'; message: string }
  | { kind: 'ready'; data: ManagementData };

type Feedback = { userId: string; kind: 'success' | 'error'; message: string } | undefined;

type PendingAction =
  { userId: string; kind: 'approve' | 'reject' | 'scope' | 'revoke' } | undefined;

const roleLabels: Record<AdministratorManagedUser['role'], string> = {
  viewer: 'Viewer',
  submitter: 'Submitter',
  admin: 'Administrator',
};

const approvalLabels: Record<AdministratorManagedUser['approvalState'], string> = {
  not_requested: 'Not requested',
  pending: 'Pending approval',
  approved: 'Approved',
  rejected: 'Not approved',
};

function usePageTitle() {
  useEffect(() => {
    document.title = "Manage Users | Stat'sTheGame";
  }, []);
}

function errorMessage(error: unknown): string {
  if (error instanceof ApiResponseError && error.kind === 'unauthenticated') {
    return 'Your session is no longer valid. Sign in again to continue.';
  }

  if (error instanceof ApiResponseError || error instanceof AdminUserManagementContractError) {
    return error.message;
  }

  return 'User management could not be loaded. Please try again.';
}

function userLabel(user: AdministratorManagedUser): string {
  return user.displayName ?? `Account ${user.id}`;
}

function accessAudit(user: AdministratorManagedUser): string | null {
  if (!user.submitterAccessUpdatedAt) {
    return null;
  }

  const actor = user.submitterAccessUpdatedBy
    ? (user.submitterAccessUpdatedBy.displayName ?? `Account ${user.submitterAccessUpdatedBy.id}`)
    : 'a former administrator';

  return `${new Date(user.submitterAccessUpdatedAt).toLocaleString()} by ${actor}`;
}

interface ManagedUserCardProps {
  user: AdministratorManagedUser;
  availableScopes: AdministratorCompetitionScope[];
  pendingAction: PendingAction;
  feedback: Feedback;
  onUpdate: (
    user: AdministratorManagedUser,
    update: AdministratorSubmitterAccessUpdate,
    kind: NonNullable<PendingAction>['kind'],
  ) => Promise<void>;
}

function ManagedUserCard({
  user,
  availableScopes,
  pendingAction,
  feedback,
  onUpdate,
}: ManagedUserCardProps) {
  const isSubmitter = user.role === 'submitter' && user.approvalState === 'approved';
  const hasPendingRequest = user.role === 'viewer' && user.approvalState === 'pending';
  const assignedIds = useMemo(
    () => user.competitionScopes.map((scope) => scope.competitionId),
    [user.competitionScopes],
  );
  const initialScopeIds = useMemo(
    () =>
      hasPendingRequest && user.requestedCompetition
        ? [user.requestedCompetition.competitionId]
        : assignedIds,
    [assignedIds, hasPendingRequest, user.requestedCompetition],
  );
  const [selectedScopeIds, setSelectedScopeIds] = useState<string[]>(initialScopeIds);
  const [selectionError, setSelectionError] = useState<string | null>(null);
  const isBusy = pendingAction?.userId === user.id;
  const isManageable = user.role !== 'admin' && !user.disabled;
  const canManageAccess = isManageable && (isSubmitter || hasPendingRequest);
  const audit = accessAudit(user);
  const selectionChanged =
    [...selectedScopeIds].sort().join(',') !== [...assignedIds].sort().join(',');
  const pendingActionMessage =
    pendingAction?.kind === 'approve'
      ? 'Approving submitter access. Please wait.'
      : pendingAction?.kind === 'reject'
        ? 'Rejecting the submitter access request. Please wait.'
        : pendingAction?.kind === 'scope'
          ? 'Saving competition scope changes. Please wait.'
          : pendingAction?.kind === 'revoke'
            ? 'Revoking submitter access. Please wait.'
            : null;

  useEffect(() => {
    setSelectedScopeIds(initialScopeIds);
    setSelectionError(null);
  }, [initialScopeIds]);

  function toggleScope(competitionId: string) {
    setSelectionError(null);
    setSelectedScopeIds((current) =>
      current.includes(competitionId)
        ? current.filter((id) => id !== competitionId)
        : [...current, competitionId],
    );
  }

  async function saveAccess(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (selectedScopeIds.length === 0) {
      setSelectionError('Select at least one competition scope.');
      return;
    }

    await onUpdate(
      user,
      { approved: true, competitionIds: selectedScopeIds },
      isSubmitter ? 'scope' : 'approve',
    );
  }

  return (
    <article className="admin-user-card" aria-labelledby={`admin-user-${user.id}`}>
      <header className="admin-user-card__header">
        <div>
          <p className="admin-user-card__id">Account {user.id}</p>
          <h2 id={`admin-user-${user.id}`}>{userLabel(user)}</h2>
        </div>
        <span className={`admin-role-badge admin-role-badge--${user.role}`}>
          {roleLabels[user.role]}
        </span>
      </header>

      <dl className="admin-user-facts">
        <div>
          <dt>Role</dt>
          <dd>{roleLabels[user.role]}</dd>
        </div>
        <div>
          <dt>Approval</dt>
          <dd>{approvalLabels[user.approvalState]}</dd>
        </div>
        <div>
          <dt>Competition scope</dt>
          <dd>
            {user.competitionScopes.length > 0
              ? user.competitionScopes.map((scope) => scope.name).join(', ')
              : 'None assigned'}
          </dd>
        </div>
        <div>
          <dt>Requested competition</dt>
          <dd>{user.requestedCompetition?.name ?? 'None requested'}</dd>
        </div>
        <div>
          <dt>Account state</dt>
          <dd>{user.disabled ? 'Disabled' : 'Active'}</dd>
        </div>
        {audit ? (
          <div className="admin-user-facts__audit">
            <dt>Last access change</dt>
            <dd>{audit}</dd>
          </div>
        ) : null}
      </dl>

      {hasPendingRequest && isManageable ? (
        <p className="admin-user-card__request-state" role="status">
          <strong>Submitter access requested.</strong> This request is awaiting administrator
          review. Approval grants the requested competition; rejection does not assign any scope.
        </p>
      ) : null}

      {canManageAccess ? (
        <form className="admin-access-form" onSubmit={(event) => void saveAccess(event)}>
          <fieldset disabled={isBusy} aria-describedby={`scope-help-${user.id}`}>
            <legend>
              {isSubmitter ? 'Update competition scope' : 'Approve requested competition'}
            </legend>
            <p id={`scope-help-${user.id}`} className="field-help">
              {isSubmitter
                ? 'Submission permission takes effect only for the selected competitions.'
                : 'Approval grants exactly the competition selected by the requester.'}
            </p>
            {isSubmitter && availableScopes.length > 0 ? (
              <div className="admin-scope-options">
                {availableScopes.map((scope) => (
                  <label key={scope.competitionId}>
                    <input
                      type="checkbox"
                      checked={selectedScopeIds.includes(scope.competitionId)}
                      onChange={() => toggleScope(scope.competitionId)}
                    />
                    <span>{scope.name}</span>
                  </label>
                ))}
              </div>
            ) : isSubmitter ? (
              <p className="admin-access-form__empty" role="status">
                No competition scopes are available. This submitter cannot be re-scoped yet.
              </p>
            ) : user.requestedCompetition ? (
              <p className="admin-access-form__requested-scope">
                <strong>{user.requestedCompetition.name}</strong>
              </p>
            ) : (
              <p className="admin-access-form__empty" role="status">
                This legacy pending request has no competition. Reject it so the user can submit a
                corrected competition-scoped request.
              </p>
            )}
          </fieldset>

          {selectionError ? (
            <p className="admin-access-form__error" role="alert">
              {selectionError}
            </p>
          ) : null}

          <div className="admin-access-form__actions">
            <button
              className="button button--primary"
              type="submit"
              disabled={
                isBusy ||
                (isSubmitter
                  ? availableScopes.length === 0 || !selectionChanged
                  : !user.requestedCompetition)
              }
            >
              {isBusy && pendingAction?.kind === 'approve'
                ? 'Approving submitter...'
                : isBusy && pendingAction?.kind === 'scope'
                  ? 'Saving scope...'
                  : isSubmitter
                    ? 'Save scope changes'
                    : 'Approve submitter'}
            </button>
            {isSubmitter ? (
              <button
                className="button button--danger"
                type="button"
                disabled={isBusy}
                onClick={() =>
                  void onUpdate(user, { approved: false, competitionIds: [] }, 'revoke')
                }
              >
                {isBusy && pendingAction.kind === 'revoke'
                  ? 'Revoking access...'
                  : 'Revoke submitter access'}
              </button>
            ) : hasPendingRequest ? (
              <button
                className="button button--danger"
                type="button"
                disabled={isBusy}
                onClick={() =>
                  void onUpdate(user, { approved: false, competitionIds: [] }, 'reject')
                }
              >
                {isBusy && pendingAction.kind === 'reject'
                  ? 'Rejecting request...'
                  : 'Reject request'}
              </button>
            ) : null}
          </div>

          {isBusy && pendingActionMessage ? (
            <p className="admin-access-form__progress" role="status" aria-live="polite">
              {pendingActionMessage}
            </p>
          ) : null}
        </form>
      ) : (
        <p className="admin-user-card__protected" role="status">
          {user.role === 'admin'
            ? 'Administrator accounts are protected from submitter access changes.'
            : user.disabled
              ? 'Disabled accounts cannot receive submitter access changes.'
              : user.approvalState === 'not_requested'
                ? 'No submitter access request is currently awaiting review.'
                : user.approvalState === 'rejected'
                  ? 'No submitter access request is currently awaiting review. The previous request was rejected; the user must make a new request before approval.'
                  : user.approvalState === 'approved'
                    ? "No submitter access request is currently awaiting review. This account's previously approved submitter access has been revoked."
                    : 'This account has no actionable pending submitter request.'}
        </p>
      )}

      {feedback?.userId === user.id ? (
        <p
          className={`admin-access-feedback admin-access-feedback--${feedback.kind}`}
          role={feedback.kind === 'error' ? 'alert' : 'status'}
        >
          {feedback.message}
        </p>
      ) : null}
    </article>
  );
}

export function AdminUsersPage() {
  const { isAuthenticated, isLoading } = useAuth();
  const client = useAuthenticatedApiClient();
  const [pageState, setPageState] = useState<PageState>({ kind: 'loading' });
  const [filter, setFilter] = useState('');
  const [pendingAction, setPendingAction] = useState<PendingAction>();
  const [feedback, setFeedback] = useState<Feedback>();

  usePageTitle();

  const loadUsers = useCallback(
    async (signal?: AbortSignal) => {
      setPageState({ kind: 'loading' });
      setFeedback(undefined);

      try {
        const profile = await getCurrentUserProfile(client, signal);

        if (profile.role !== 'admin') {
          setPageState({ kind: 'forbidden' });
          return;
        }

        const data = await getAdministratorUserManagement(client, signal);
        setPageState({ kind: 'ready', data });
      } catch (error) {
        if (signal?.aborted) {
          return;
        }

        if (error instanceof ApiResponseError && error.kind === 'forbidden') {
          setPageState({ kind: 'forbidden' });
          return;
        }

        setPageState({ kind: 'error', message: errorMessage(error) });
      }
    },
    [client],
  );

  useEffect(() => {
    if (isLoading || !isAuthenticated) {
      return;
    }

    const controller = new AbortController();
    void loadUsers(controller.signal);

    return () => controller.abort();
  }, [isAuthenticated, isLoading, loadUsers]);

  async function updateAccess(
    user: AdministratorManagedUser,
    update: AdministratorSubmitterAccessUpdate,
    kind: NonNullable<PendingAction>['kind'],
  ) {
    setPendingAction({ userId: user.id, kind });
    setFeedback(undefined);

    try {
      const updatedUser =
        kind === 'reject'
          ? await rejectAdministratorSubmitterAccessRequest(client, user.id)
          : await updateAdministratorSubmitterAccess(client, user.id, update);

      setPageState((current) =>
        current.kind === 'ready'
          ? {
              kind: 'ready',
              data: {
                ...current.data,
                users: current.data.users.map((candidate) =>
                  candidate.id === updatedUser.id ? updatedUser : candidate,
                ),
              },
            }
          : current,
      );
      setFeedback({
        userId: user.id,
        kind: 'success',
        message:
          kind === 'revoke'
            ? `Submitter access was revoked for ${userLabel(user)}.`
            : kind === 'reject'
              ? `Submitter request was rejected for ${userLabel(user)}.`
              : kind === 'scope'
                ? `Competition scope was updated for ${userLabel(user)}.`
                : `${userLabel(user)} is now an approved submitter.`,
      });
    } catch (error) {
      setFeedback({
        userId: user.id,
        kind: 'error',
        message:
          error instanceof ApiResponseError || error instanceof AdminUserManagementContractError
            ? error.message
            : 'The submitter access change could not be saved. Please try again.',
      });
    } finally {
      setPendingAction(undefined);
    }
  }

  if (!isLoading && !isAuthenticated) {
    return <Navigate to="/sign-in" replace />;
  }

  const normalizedFilter = filter.trim().toLocaleLowerCase();
  const visibleUsers =
    pageState.kind === 'ready'
      ? pageState.data.users.filter((user) => {
          if (!normalizedFilter) {
            return true;
          }

          return [
            user.displayName,
            user.id,
            roleLabels[user.role],
            approvalLabels[user.approvalState],
            user.requestedCompetition?.name,
            ...user.competitionScopes.map((scope) => scope.name),
          ]
            .filter(Boolean)
            .some((value) => value!.toLocaleLowerCase().includes(normalizedFilter));
        })
      : [];

  return (
    <section className="admin-users-page content-boundary" aria-labelledby="admin-users-title">
      <header className="page-heading admin-users-page__heading">
        <p className="eyebrow">Administrator workspace</p>
