    command: 'SELECT',
    oid: 0,
    fields: [],
  };
}

function createExecutor(...results: Record<string, unknown>[][]) {
  const query = vi.fn();

  for (const rows of results) {
    query.mockResolvedValueOnce(queryResult(rows));
  }

  return {
    executor: { query } as unknown as QueryExecutor,
    query,
  };
}

