import { Pool, type PoolClient } from 'pg';
import { afterAll, beforeAll, describe, expect, test } from 'vitest';

import { executeQuery } from '../../src/database';
import { createSubmitterAccessRepository } from '../../src/modules/submitter-access/submitter-access.repository';
import { assertSafeTestDatabase } from '../../scripts/test-database-safety';

const sourcePrefix = `submitter-access-test-${process.pid}`;

describe.sequential('submitter access request database integration', () => {
  let pool: Pool | undefined;

  function databasePool(): Pool {
    if (!pool) {
      throw new Error('Test database pool has not been initialised.');
    }

    return pool;
  }

  async function withRolledBackTransaction(
    operation: (client: PoolClient) => Promise<void>,
  ): Promise<void> {
    const client = await databasePool().connect();

    try {
      await client.query('BEGIN');
      await operation(client);
    } finally {
      await client.query('ROLLBACK');
      client.release();
    }
  }

  async function insertAccount(
    client: PoolClient,
    suffix: string,
    approvalState: 'not_requested' | 'pending' | 'approved' | 'rejected',
  ): Promise<string> {
    const result = await executeQuery<{ accountId: string }>(
      client,
      `
        INSERT INTO app_user (
          auth_provider,
          auth_subject,
          submitter_approval_state
        )
        VALUES ('test', $1, $2)
        RETURNING app_user_id::text AS "accountId"
      `,
      [`${sourcePrefix}-${suffix}`, approvalState],
    );

    return result.rows[0].accountId;
  }

  async function insertCompetition(client: PoolClient, suffix: string): Promise<string> {
    const result = await executeQuery<{ competitionId: string }>(
      client,
      `
        INSERT INTO competition (name)
        VALUES ($1)
        RETURNING competition_id::text AS "competitionId"
      `,
      [`${sourcePrefix}-${suffix}`],
    );

    return result.rows[0].competitionId;
  }

  beforeAll(() => {
    const databaseUrl = assertSafeTestDatabase(
      process.env.DATABASE_URL_TEST,
      process.env.DATABASE_URL,
      process.env.NODE_ENV,
    );

    pool = new Pool({
      connectionString: databaseUrl.toString(),
    });
  });

  afterAll(async () => {
    if (pool) {
      await pool.end();
    }
  });

  test('persists a pending request and prevents a second active request', async () => {
    await withRolledBackTransaction(async (client) => {
      const accountId = await insertAccount(client, 'new-request', 'not_requested');
      const competitionId = await insertCompetition(client, 'new-request-competition');
      const repository = createSubmitterAccessRepository(client);

      await expect(repository.requestAccess(accountId, competitionId)).resolves.toEqual({
        accountId,
        approvalState: 'pending',
        requestedCompetition: {
          competitionId,
          name: `${sourcePrefix}-new-request-competition`,
        },
      });

      const persisted = await executeQuery<{
        approvalState: string;
        requestedCompetitionId: string | null;
      }>(
        client,
        `
          SELECT
            submitter_approval_state AS "approvalState",
            submitter_requested_competition_id::text AS "requestedCompetitionId"
          FROM app_user
          WHERE app_user_id = $1
        `,
        [accountId],
      );

      expect(persisted.rows[0].approvalState).toBe('pending');
      expect(persisted.rows[0].requestedCompetitionId).toBe(competitionId);

      await expect(repository.requestAccess(accountId, competitionId)).rejects.toMatchObject({
        code: 'REQUEST_ALREADY_PENDING',
      });
    });
  });

  test('allows a previously rejected account to request access again', async () => {
    await withRolledBackTransaction(async (client) => {
      const accountId = await insertAccount(client, 'rejected-request', 'rejected');
      const competitionId = await insertCompetition(client, 'rejected-request-competition');
      const repository = createSubmitterAccessRepository(client);

      await expect(repository.requestAccess(accountId, competitionId)).resolves.toEqual({
        accountId,
        approvalState: 'pending',
        requestedCompetition: {
          competitionId,
          name: `${sourcePrefix}-rejected-request-competition`,
        },
      });

      const persisted = await executeQuery<{ approvalState: string }>(
        client,
        `
          SELECT submitter_approval_state AS "approvalState"
          FROM app_user
          WHERE app_user_id = $1
        `,
        [accountId],
      );

      expect(persisted.rows[0].approvalState).toBe('pending');
    });
  });

  test('does not change an already-approved submitter', async () => {
    await withRolledBackTransaction(async (client) => {
      const accountId = await insertAccount(client, 'approved-request', 'approved');
      const competitionId = await insertCompetition(client, 'approved-request-competition');
      const repository = createSubmitterAccessRepository(client);

      await expect(repository.requestAccess(accountId, competitionId)).rejects.toMatchObject({
        code: 'SUBMITTER_ALREADY_APPROVED',
      });

      const persisted = await executeQuery<{ approvalState: string }>(
        client,
        `
          SELECT submitter_approval_state AS "approvalState"
          FROM app_user
          WHERE app_user_id = $1
        `,
        [accountId],
      );

      expect(persisted.rows[0].approvalState).toBe('approved');
    });
  });

  test('does not create a pending request for a nonexistent competition', async () => {
    await withRolledBackTransaction(async (client) => {
      const accountId = await insertAccount(client, 'missing-competition', 'not_requested');
      const repository = createSubmitterAccessRepository(client);

      await expect(repository.requestAccess(accountId, '9223372036854775806')).rejects.toThrow(
        'The requested competition does not exist.',
      );

      const persisted = await executeQuery<{
        approvalState: string;
        requestedCompetitionId: string | null;
      }>(
        client,
        `
          SELECT
            submitter_approval_state AS "approvalState",
            submitter_requested_competition_id::text AS "requestedCompetitionId"
          FROM app_user
          WHERE app_user_id = $1
        `,
        [accountId],
      );

      expect(persisted.rows[0]).toEqual({
        approvalState: 'not_requested',
        requestedCompetitionId: null,
      });
    });
  });
});
import request from 'supertest';
import { describe, expect, test, vi } from 'vitest';

import type { VerifyAccessToken } from '../../src/auth/supabase-auth';
import type { SubmitterAccessService } from '../../src/modules/submitter-access/submitter-access.service';
import {
  InvalidRequestedCompetitionError,
  SubmitterAccessConflictError,
} from '../../src/modules/submitter-access/submitter-access.errors';
import { createTestAccount, createTestApp } from '../test-app';

function mockSubmitterAccessService(): SubmitterAccessService {
  return {
    requestAccess: vi.fn<SubmitterAccessService['requestAccess']>().mockResolvedValue({
      data: {
        accountId: '1',
        approvalState: 'pending',
        requestedCompetition: { competitionId: '7', name: 'Premier T20' },
      },
    }),
  };
}

describe('submitter access request API', () => {
  test('rejects unauthenticated requests before request processing', async () => {
    const verifyAccessToken = vi.fn<VerifyAccessToken>();
    const service = mockSubmitterAccessService();

    const response = await request(
      createTestApp(verifyAccessToken, undefined, undefined, undefined, undefined, service),
    )
      .post('/api/v1/submitter-access-requests')
      .expect('WWW-Authenticate', 'Bearer')
      .expect(401);

    expect(verifyAccessToken).not.toHaveBeenCalled();
    expect(service.requestAccess).not.toHaveBeenCalled();
    expect(response.body).toEqual({
      error: {
        code: 'UNAUTHORIZED',
        message: 'A valid authentication token is required.',
      },
    });
  });

  test('creates a pending request for the authenticated application account', async () => {
    const service = mockSubmitterAccessService();
    const account = createTestAccount({
      accountId: '42',
      approvalState: 'not_requested',
    });

    const synchronizeAccount = async () => account;

    const response = await request(
      createTestApp(undefined, undefined, synchronizeAccount, undefined, undefined, service),
    )
      .post('/api/v1/submitter-access-requests')
      .set('Authorization', 'Bearer test-token')
      .send({ competitionId: '7' })
      .expect(201);

    expect(service.requestAccess).toHaveBeenCalledOnce();
    expect(service.requestAccess).toHaveBeenCalledWith(account, { competitionId: '7' });

    expect(response.body).toEqual({
      data: {
        accountId: '1',
        approvalState: 'pending',
        requestedCompetition: { competitionId: '7', name: 'Premier T20' },
      },
    });
  });

  test('rejects a duplicate active request', async () => {
    const service = mockSubmitterAccessService();

    vi.mocked(service.requestAccess).mockRejectedValue(
      new SubmitterAccessConflictError(
        'REQUEST_ALREADY_PENDING',
        'A submitter access request is already pending.',
      ),
    );

    const response = await request(
      createTestApp(undefined, undefined, undefined, undefined, undefined, service),
    )
      .post('/api/v1/submitter-access-requests')
      .set('Authorization', 'Bearer test-token')
      .send({ competitionId: '7' })
      .expect(409);

    expect(response.body).toEqual({
      error: {
        code: 'REQUEST_ALREADY_PENDING',
        message: 'A submitter access request is already pending.',
      },
    });
  });

  test('rejects an already-approved submitter', async () => {
    const service = mockSubmitterAccessService();

    vi.mocked(service.requestAccess).mockRejectedValue(
      new SubmitterAccessConflictError(
        'SUBMITTER_ALREADY_APPROVED',
        'The authenticated account is already an approved submitter.',
      ),
    );

    const response = await request(
      createTestApp(undefined, undefined, undefined, undefined, undefined, service),
    )
      .post('/api/v1/submitter-access-requests')
      .set('Authorization', 'Bearer test-token')
      .send({ competitionId: '7' })
      .expect(409);

    expect(response.body).toEqual({
      error: {
        code: 'SUBMITTER_ALREADY_APPROVED',
        message: 'The authenticated account is already an approved submitter.',
      },
    });
  });

  test.each([{ fixtureId: '42' }, { competitionId: 'not-an-id' }, {}])(
    'rejects a request without a valid competition identifier',
    async (body) => {
      const service = mockSubmitterAccessService();

      const response = await request(
        createTestApp(undefined, undefined, undefined, undefined, undefined, service),
      )
        .post('/api/v1/submitter-access-requests')
        .set('Authorization', 'Bearer test-token')
        .send(body)
        .expect(422);

      expect(service.requestAccess).not.toHaveBeenCalled();
      expect(response.body.error).toMatchObject({ code: 'VALIDATION_FAILED' });
    },
  );

  test('rejects a competition that no longer exists', async () => {
    const service = mockSubmitterAccessService();
    vi.mocked(service.requestAccess).mockRejectedValue(new InvalidRequestedCompetitionError());

    const response = await request(
      createTestApp(undefined, undefined, undefined, undefined, undefined, service),
    )
      .post('/api/v1/submitter-access-requests')
      .set('Authorization', 'Bearer test-token')
      .send({ competitionId: '99' })
      .expect(422);

    expect(response.body.error).toMatchObject({
      code: 'INVALID_COMPETITION_SCOPE',
      message: 'The requested competition does not exist.',
    });
  });
});
import { describe, expect, test, vi } from 'vitest';

import type { QueryExecutor } from '../../src/database';
import { createSubmitterAccessRepository } from '../../src/modules/submitter-access/submitter-access.repository';

function queryResult(rows: Record<string, unknown>[]) {
  return {
    rows,
    rowCount: rows.length,
    command: 'SELECT',
    oid: 0,
    fields: [],
  };
}

function createExecutor(...results: Record<string, unknown>[][]) {
  const query = vi.fn();

  for (const rows of results) {
    query.mockResolvedValueOnce(queryResult(rows));
  }

  return {
    executor: { query } as unknown as QueryExecutor,
    query,
  };
}

describe('submitter access repository', () => {
  test('atomically changes an eligible account to pending', async () => {
    const { executor, query } = createExecutor([
      {
        accountId: '42',
        approvalState: 'pending',
        disabledAt: null,
        requestedCompetitionId: '7',
        requestedCompetitionName: 'Premier T20',
      },
    ]);

    const repository = createSubmitterAccessRepository(executor);

    await expect(repository.requestAccess('42', '7')).resolves.toEqual({
      accountId: '42',
      approvalState: 'pending',
      requestedCompetition: { competitionId: '7', name: 'Premier T20' },
    });

    expect(query).toHaveBeenCalledTimes(1);
    expect(query).toHaveBeenCalledWith(
      expect.stringContaining("submitter_approval_state IN ('not_requested', 'rejected')"),
      ['42', '7'],
    );
  });

  test('rejects an account with an existing pending request', async () => {
    const { executor } = createExecutor(
      [],
      [
        {
          accountId: '42',
          approvalState: 'pending',
          disabledAt: null,
          competitionExists: true,
        },
      ],
    );

    const repository = createSubmitterAccessRepository(executor);

    await expect(repository.requestAccess('42', '7')).rejects.toMatchObject({
      code: 'REQUEST_ALREADY_PENDING',
    });
  });

  test('rejects an already-approved submitter', async () => {
    const { executor } = createExecutor(
      [],
      [
        {
          accountId: '42',
          approvalState: 'approved',
          disabledAt: null,
          competitionExists: true,
        },
      ],
    );

    const repository = createSubmitterAccessRepository(executor);

    await expect(repository.requestAccess('42', '7')).rejects.toMatchObject({
      code: 'SUBMITTER_ALREADY_APPROVED',
    });
  });

  test('fails closed for an unsupported persisted approval state', async () => {
    const { executor } = createExecutor(
      [],
      [
        {
          accountId: '42',
          approvalState: 'unexpected-state',
          disabledAt: null,
          competitionExists: true,
        },
      ],
    );

    const repository = createSubmitterAccessRepository(executor);

    await expect(repository.requestAccess('42', '7')).rejects.toThrow('unsupported approval state');
  });

  test('rejects a competition that does not exist without changing the account', async () => {
    const { executor } = createExecutor(
      [],
      [
        {
          accountId: '42',
          approvalState: 'not_requested',
          disabledAt: null,
          competitionExists: false,
        },
      ],
    );

    const repository = createSubmitterAccessRepository(executor);

    await expect(repository.requestAccess('42', '99')).rejects.toThrow(
      'The requested competition does not exist.',
    );
  });
});
