    await expect(service.rejectSubmitterAccessRequest(administrator, '42')).rejects.toMatchObject({
      code: 'SELF_MANAGEMENT_NOT_ALLOWED',
    });
    expect(adminRepository.rejectSubmitterAccessRequest).not.toHaveBeenCalled();
  });
});

