import {
  correctionRequestSchema,
  submissionEventIdSchema,
  submissionRequestSchema,
} from '@sport-analytics/contracts';
import type { RequestHandler, Response } from 'express';

import { rejectAuthorization } from '../../middleware/authorization-response';
import type { ApplicationAccount } from '../accounts/account';
import {
  SubmissionConflictError,
  SubmissionForbiddenError,
  SubmissionValidationError,
} from './submission.errors';
import type { SubmissionService } from './submission.service';

function getAuthenticatedAccount(response: Response): ApplicationAccount {
  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;

  if (!account) {
    throw new Error('Submission controller requires an authenticated application account');
  }

  return account;
}

export function createSubmissionController(service: SubmissionService): RequestHandler {
  return (request, response, next) => {
    const parsed = submissionRequestSchema.safeParse(request.body);

    if (!parsed.success) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The submission is invalid.',
          details: parsed.error.issues.map((issue) => {
            const eventPathIndex = issue.path[0] === 'events' ? issue.path[1] : undefined;
            return {
              code: 'INVALID_FIELD',
              message: issue.message,
              ...(issue.path.length > 0 ? { field: issue.path.join('.') } : {}),
              ...(typeof eventPathIndex === 'number' ? { eventIndex: eventPathIndex } : {}),
            };
          }),
        },
      });
      return;
    }

    let account: ApplicationAccount;
    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .submit(account, parsed.data)
      .then((submission) => {
        response.status(201).json(submission);
      })
      .catch((error: unknown) => {
        if (error instanceof SubmissionForbiddenError) {
          rejectAuthorization(response);
          return;
        }

        if (error instanceof SubmissionValidationError) {
          response.status(422).json({
            error: {
              code: 'VALIDATION_FAILED',
              message: error.message,
              details: error.details,
            },
          });
          return;
        }

        if (error instanceof SubmissionConflictError) {
          response.status(409).json({
            error: {
              code: error.code,
              message: error.message,
            },
          });
          return;
        }

        next(error);
      });
  };
}

export function createCorrectionController(service: SubmissionService): RequestHandler {
  return (request, response, next) => {
    const eventId = submissionEventIdSchema.safeParse(request.params.eventId);
    const parsed = correctionRequestSchema.safeParse(request.body);

    if (!eventId.success || !parsed.success) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The correction is invalid.',
          details: [
            ...(!eventId.success
              ? eventId.error.issues.map((issue) => ({
                  code: 'INVALID_FIELD',
                  message: issue.message,
                  field: 'eventId',
                }))
              : []),
            ...(!parsed.success
              ? parsed.error.issues.map((issue) => ({
                  code: 'INVALID_FIELD',
                  message: issue.message,
                  ...(issue.path.length > 0 ? { field: issue.path.join('.') } : {}),
                }))
              : []),
          ],
        },
      });
      return;
    }

    let account: ApplicationAccount;
    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .correct(account, eventId.data, parsed.data)
      .then((correction) => response.status(200).json(correction))
      .catch((error: unknown) => {
        if (error instanceof SubmissionForbiddenError) {
          rejectAuthorization(response);
          return;
        }

        if (error instanceof SubmissionValidationError) {
          response.status(422).json({
            error: {
              code: 'VALIDATION_FAILED',
              message: error.message,
              details: error.details,
            },
          });
          return;
        }

        if (error instanceof SubmissionConflictError) {
          response.status(409).json({
            error: { code: error.code, message: error.message },
          });
          return;
        }

        next(error);
      });
  };
}
import { Router } from 'express';

import type { VerifyAccessToken } from '../../auth/supabase-auth';
import { requireAuthentication } from '../../middleware/require-authentication';
import { requireSubmitter } from '../../middleware/require-authorization';
import type { SynchronizeAccount } from '../accounts/account.service';
import { createCorrectionController, createSubmissionController } from './submission.controller';
import { createSubmissionRateLimit } from './submission-rate-limit';
import type { SubmissionService } from './submission.service';

export function createSubmissionRouter(
  verifyAccessToken: VerifyAccessToken,
  synchronizeAccount: SynchronizeAccount,
  service: SubmissionService,
): Router {
  const router = Router();

  router.post(
    '/submissions',
    requireAuthentication(verifyAccessToken, synchronizeAccount),
    requireSubmitter(),
    createSubmissionRateLimit(),
    createSubmissionController(service),
  );

  router.put(
    '/submissions/events/:eventId',
    requireAuthentication(verifyAccessToken, synchronizeAccount),
    requireSubmitter(),
    createSubmissionRateLimit(),
    createCorrectionController(service),
  );

  return router;
}
import 'dotenv/config';

import { createApp } from './app';
import { loadEnvironment } from './config/env';
import { closeDatabasePool } from './database';

const environment = loadEnvironment();
const app = createApp({ environment });

const server = app.listen(environment.PORT, () => {
  console.log(`Sport Analytics API listening on port ${environment.PORT}`);
});

let shuttingDown = false;

function closeHttpServer(): Promise<void> {
  return new Promise((resolve, reject) => {
    server.close((error) => {
      if (error) {
        reject(error);
        return;
      }

      resolve();
    });
  });
}

async function shutdown(signal: string): Promise<void> {
  if (shuttingDown) {
    return;
  }

  shuttingDown = true;

  console.log(`${signal} received; shutting down`);

  try {
    await closeHttpServer();
  } catch {
    console.error('Failed to close HTTP server cleanly.');
    process.exitCode = 1;
  }

  try {
    await closeDatabasePool();
  } catch {
    console.error('Failed to close database pool cleanly.');
    process.exitCode = 1;
  }
}

process.on('SIGINT', () => {
  void shutdown('SIGINT');
});

process.on('SIGTERM', () => {
  void shutdown('SIGTERM');
});
