      .expect(201);
    await executeQuery(
      databasePool(),
      `
        UPDATE fixture
        SET first_seen_in = (
          SELECT submission_id FROM submission WHERE fixture_id = $1 ORDER BY submission_id ASC LIMIT 1
        )
