        }
      }
    }

    for (const [field, participantId] of participantFields) {
      if (!validParticipants.has(participantId)) {
        eventDetails.push({
          code: 'INVALID_PARTICIPANT',
          message: 'The participant does not belong to the submitted fixture.',
          field,
          eventIndex,
        });
