  test('rejects each missing required field for the field that is missing', () => {
    const required = [
      'eventId',
      'inningsId',
      'sequenceNumber',
      'overNumber',
      'positionInOver',
      'ballNumber',
      'strikerId',
      'nonStrikerId',
      'bowlerId',
      'runs',
