    })),
  );
}

function currentUser(
  role: ApplicationRole,
  approvalState: CurrentUserProfile['approvalState'],
  competitionIds: string[] = [],
) {
  return response(200, {
    user: {
      id: '17',
      subject: 'approved-user',
